(()=>{'use strict';let worker=null,sequence=0;const jobs=new Map();
function run(rows,progress,options={}){if(!worker){worker=new Worker(new URL('model-worker.js?v=20261017',document.baseURI));worker.onmessage=({data})=>{const job=jobs.get(data.id);if(!job)return;if(data.type==='progress'){job.progress?.(data);return;}jobs.delete(data.id);if(data.type==='error')job.reject(Error(data.message));else job.resolve(data);};worker.onerror=()=>{jobs.forEach(j=>j.reject(Error('浏览器计算中断，请重试')));jobs.clear();worker.terminate();worker=null;};}return new Promise((resolve,reject)=>{const id=++sequence;jobs.set(id,{resolve,reject,progress});worker.postMessage({id,rows,...options});});}
function fromChanges(changes){const schema=window.RESPGRAPH_INPUT,raw={...changes};for(const t of ['T0_T1','T0_T2']){raw['FTV_LD_diff_'+t]=raw['FTV_pch_'+t]-raw['LD_pch_'+t];raw['SPHERICITY_BPE_index_'+t]=raw['Sphericity_pch_'+t]*raw['BPE_pch_'+t];}const features={};for(const f of schema.features){const value=raw[f],r=schema.recipe[f];if(!Number.isFinite(value)||Math.abs(value)>1e7)throw Error('请填写完整、有效的检查变化值');features[f]=value*r.slope+r.intercept;if(Math.abs(features[f])>=1e6)throw Error('检查数值超出可计算范围');}return features;}
function fromMeasurements(measurements){const changes={};for(const k of ['FTV','LD','BPE','Sphericity']){const a=measurements[k];if(!a||a.some(v=>!Number.isFinite(v)||v<0)||a[0]<=0)throw Error('三期检查值需完整，治疗前数值须大于0');for(let t=1;t<=2;t++)changes[k+'_pch_T0_T'+t]=(a[t]-a[0])/a[0]*100;}return {features:fromChanges(changes),changes};}
function changesFromFeatures(features){const out={};for(const [f,r] of Object.entries(window.RESPGRAPH_INPUT.recipe))if(f.includes('_pch_'))out[f]=(features[f]-r.intercept)/r.slope;return out;}
window.RespInference={run,fromChanges,fromMeasurements,changesFromFeatures};})();

