function segmentHitsBox(a,b,r){let lo=0,hi=1;for(const [key,min,max] of [['x',r.left,r.right],['y',r.top,r.bottom]]){const d=b[key]-a[key];if(Math.abs(d)<1e-9){if(a[key]<min||a[key]>max)return false;}else{const t1=(min-a[key])/d,t2=(max-a[key])/d;lo=Math.max(lo,Math.min(t1,t2));hi=Math.min(hi,Math.max(t1,t2));if(lo>hi)return false;}}return true;}
